

library(SingleCellExperiment)
library(HDF5Array)

#' Load CellRanger output into a SingleCellExperiment object
#' 
#' Count are not loaded into memory but are made accessible by the object
#' 
#' @param TENx_file path to the .h5 file generated by CellRanger
#' @return SingleCellExperiment object
read10x <- function(TENx_file) {
  # Load features metadata
  features_metadata <- h5read(TENx_file,"/matrix/features",compoundAsDataFrame = TRUE)
  features_metadata <- 
    features_metadata[setdiff(names(features_metadata),"_all_tag_keys")] |>
    as.data.frame()
  rownames(features_metadata) <- features_metadata$id
  
  # Load counts and make the SingleCellExperiment object
  o <- SingleCellExperiment(
    List(counts = TENxMatrix(TENx_file)),
    rowData = features_metadata
  )
  rownames(o) <- make.unique(rowData(o)$name) # Use gene symbols as rownames
  
  o
}



